import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    odd_cnt = 0
    has_even = False
    for x in a:
        if x % 2 == 0:
            has_even = True
        else:
            odd_cnt += 1

    if has_even:
        print(odd_cnt)
    else:
        print(-1)

if __name__ == "__main__":
    main()
